export type Version = number;
/** QR mask pattern index. */
export type Mask = 0 | 1 | 2 | 3 | 4 | 5 | 6 | 7;
/** Width and height pair. */
export type Size = {
    /** Pixel height. */
    height: number;
    /** Pixel width. */
    width: number;
};
